def get_name_counts(category):
    prompt = f"List 50 distinct {category} names with a count of their letter 'r' or 'R'. Each should be formatted as 'name - count'."
    response = llm_query(prompt)
    name_counts = {}
    for line in response.split('\n'):
        parts = line.split(' - ')
        if len(parts) == 2:
            name, count = parts
            try:
                name_counts[name.strip()] = int(count.strip())
            except ValueError:
                continue  # Skip lines with formatting errors
    return name_counts

